<?php require '../includes/core.php';$u=require_user();if(!has_subscription($u)){layout_start('Ativar plano',$u);echo '<div class="card paywall"><h1>Escolha seu plano para começar</h1><p class="muted">O acesso à central de chamados é exclusivo de assinantes ativos.</p><a class="btn" href="'.url('plans.php').'">Ver planos</a></div>';layout_end();exit;}$plan=plan_data($u);$q=db()->prepare('SELECT status,COUNT(*) n FROM tickets WHERE user_id=? GROUP BY status');$q->execute([$u['id']]);$counts=[];foreach($q as $r)$counts[$r['status']]=$r['n'];$q=db()->prepare("SELECT COUNT(*) FROM tickets WHERE user_id=? AND created_at>=DATE_FORMAT(NOW(),'%Y-%m-01')");$q->execute([$u['id']]);$used=(int)$q->fetchColumn();$q=db()->prepare('SELECT id,subject,status,priority,created_at FROM tickets WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$q->execute([$u['id']]);$recent=$q->fetchAll();$limit=$plan['limit']??3;layout_start('Meu painel',$u);?><section class="dashboard-hero-v9"><span class="kicker">ÁREA DO CLIENTE · <?=h(strtoupper($u['active_plan']))?></span><h1>Olá, <?=h($u['name'])?> 👋</h1><p>Seu espaço de suporte técnico, organizado para acompanhar cada solicitação.</p><div class="actions"><a class="btn" href="<?=url('user/new-ticket.php')?>">+ Abrir chamado</a><a class="btn secondary" href="<?=url('notifications.php')?>">Notificações (<?=unread_count($u['id'])?>)</a></div></section><div class="metric-grid-v9"><div class="card"><small>ABERTOS</small><div class="stat"><?=($counts['Aberto']??0)?></div></div><div class="card"><small>EM ANDAMENTO</small><div class="stat"><?=($counts['Em andamento']??0)?></div></div><div class="card"><small>RESOLVIDOS</small><div class="stat"><?=($counts['Resolvido']??0)?></div></div><div class="card"><small>DISPONÍVEIS NO MÊS</small><div class="stat"><?= $limit===0?'∞':max(0,$limit-$used) ?></div></div></div><div class="dashboard-grid-v9"><div class="card"><div class="dashboard-title-v9"><h2>Chamados recentes</h2><a href="<?=url('user/tickets.php')?>">Ver todos →</a></div><?php if(!$recent):?><p class="muted">Você ainda não abriu um chamado.</p><?php endif;?><?php foreach($recent as $t):?><a class="recent-ticket-v9" href="<?=url('user/ticket.php?id='.$t['id'])?>"><strong>#<?=$t['id']?> · <?=h($t['subject'])?></strong><?=status_badge($t['status'])?></a><?php endforeach;?></div><div class="card"><span class="kicker">SEU PLANO</span><h2><?=h($u['active_plan'])?></h2><p class="muted"><?=h($plan['info']??'Atendimento e histórico')?></p><p><strong>Novos chamados:</strong> <?= $limit===0?'Ilimitados':$limit.' por mês' ?></p><p><strong>Meta de resposta:</strong> <?=h($plan['response']??'Conforme disponibilidade')?></p><p><strong>Válido até:</strong> <?=date('d/m/Y',strtotime($u['plan_expires_at']))?></p><a class="btn secondary" href="<?=url('plans.php')?>">Comparar planos</a></div></div>
